					        <h3>Joãozinho e a Grande Invenção conta a história de uma bactéria do bem que vivia na terrinha preta comendo casquinhas de frutas e verduras e transformando elas em adubo para as plannhas! Um certo dia, misteriosamente, a comida desaparece e Joãozinho embarca em uma aventura para salvar todos os seus amigos da terrinha preta, conhecendo um universo que jamais pensou existir.</h3>
