					<h3>Espetáculo: CALIBAN <br> A Tempestade de Augusto Boal</h3>
					<p2><strong style="color: white;">				
					Tribo de Atuadores Ói Nóis Aqui Traveiz <br> 
					(Porto Alegre/RS)<br>
					Autoria: Tribo de Atuadores Ói Nóis Aqui Traveiz<br>
					Direção: Tribo de Atuadores Ói Nóis Aqui Traveiz<br>
					Gênero: Teatro de Rua <br> 
					Duração: 90 minutos<br>
					Classificação: Livre </strong></p2><br><br>
					 <button onclick="document.getElementById('id02').style.display='block'" class="w3-button w3-black">Sinopse</button>
					  <div id="id02" class="w3-modal">
					    <div class="w3-modal-content">
					      <div class="w3-container">
					        <span onclick="document.getElementById('id02').style.display='none'" class="w3-button w3-display-topright">&times;</span>
					        <h3 style="background-color: #952028; text-align: center; color: white;">CALIBAN</h3>
					        <h3 style="color: black;">Sinopse: A peça de Boal é uma resposta ao clássico “A Tempestade” de William Shakespeare. A história é vista pela perspectiva de Caliban, metáfora dos seres humanos originários da América que foram dizimados e escravizados pelos invasores colonizadores representados pelo personagem Próspero. Na versão de Boal, Próspero é tão perverso quanto os nobres europeus que usurparam o seu poder. Todos representam a violenta dominação colonial e cultural. Como em todo bom teatro político, o público deve perceber que os símbolos da obra remetem à realidade, para despertar neles – emotiva e racionalmente – uma resposta crítica fora da ficção.</h3><br>
					        <h4>Elenco: Paulo Flores, Tânia Farias, Clélio Cardoso, Marta Haas, Paula Carvalho, Eugênio Barboza, Roberto Corbo, Letícia Virtuoso, Mayura Matos, Keter Velho, Luana Rocha, Alex Pantera, Pascal Berten, André de Jesus, Márcio Leandro, Lucas Gheller, Thales Rangel, Dal Vanso, Daniel Steil, Eduardo Arruda, Júlio Kaczam, Jana Farias e Pedro Isaías Lucas</h4>
					        <button class="w3-button w3-right w3-white w3-border" onclick="document.getElementById('id02').style.display='none'">Fechar</button><br /><br><br>
