					        <h3 style="background-color: #952028; text-align: center; color: white;">Estardalhaço</h3>
					        <h3>Dois palhaços estendem sua lona e se preparam para estrelar o maior espetáculo da Terra. No repertório, a verdadeira história de amor de Leonardo DiCaprio e de sua Julieta, suas vidas e mortes, amores e guerras. O clássico é reinventado com truques, brincadeiras, números cômicos e jogos de improviso. O espetáculo que deveria abrilhantar seus artistas acaba colocando-os a beira de um abismo. O resultado final exige desembaraço, mas os palhaços aprontam um verdadeiro estardalhaço!</h3>
