					        <h3 style="background-color: #952028; text-align: center; color: white;">KUTUMPRA</h3>
					        <h3 style="color: black;">Espetáculo de humor, no qual a música e o movimento misturam-se para relatar histórias pequenas, atravessando as barreiras da linguagem, como no cinema mudo e na pantomima. No cenário, que representa um típico bairro portenho, sete personagens transformam cada objeto em instrumentos musicais: garrafas de vidro, baldes, tubos de plástico, tampas de refrigerantes, entre outros objetos, alem do próprio corpo, são usados para fazer música e tocar diferentes ritmos: chacarera, chamamé, milonga, reggae, jazz, cumbia, rock eletrônico, entre outros.</h3>
					        <h4>Elenco: Emmanuel Calderón, Roberto González, Cristian de Castro, Lucas Rivarola, Mariana Soledad Mariñelarena, Pedro Rodriguez, Juan Gudiño, Agustín Alfonso</h4>
