						         <h3 style="background-color: #952028; text-align: center; color: white;">Espetáculo: Shakespeare Inédito</h3>
						         <h3 style="color: black;"> O espetáculo procura aprofundar os universos propostos pelas obras de Shakespeare, gerando uma nova experiência construída com dramaturgia ao vivo. Os espectadores decidem que personagem e que trecho do texto deve dar início ao espetáculo, que vai sendo construído pelo elenco e pelo público. Personagens icônicos do “Bardo” aparecem juntos em um trabalho inédito. Hamlet, Julieta, Ricardo III, Lady Macbeth, Desdêmona, dentre outros, se relacionam, passeiam pelas narrativas e proporcionam novas descobertas da obra shakespeariana. Tanto a dramaturgia quanto a encenação são criadas na hora pelo diretor Ricardo Behrens, com uma sutil sugestão na cena aos atores e com gestos para mudanças de iluminação e climas musicais. Surgem encenação e história totalmente diferentes a cada função.<br><br>
						         Elenco: Intérpretes: Ricardo Behrens, Marcela Bea, Gustavo Caletti, Isabel de La Torre, Stphi Troiano</h3>
						         <button class="w3-button w3-right w3-white w3-border" onclick="document.getElementById('id18').style.display='none'">Fechar</button><br /><br><br>
						      </div>
						    </div>
						  </div>					
						</div>
