						         <h3 style="background-color: #952028; text-align: center; color: white;">Espetáculo: Diz que Sim</h3>
						         <h3 style="color: black;"> A partir do dilema central do texto "Aquele que diz sim" e dos princípios das peças de aprendizagem de Bertolt Brecht, o Coletivo Baal cria uma versão que retoma a origem musical do espetáculo. Completamente musicada, a peça narra a história de um menino que parte em uma perigosa viagem para encontrar a cura para a doença de sua mãe. Quando ele adoece no meio do caminho, o confronto com a tradição é inevitável. Sim ou Não? Tradição ou Divergência?<br><br>
						         Elenco: Beatriz Cripaldi, Gabriela Drehmer, Julia Weiss, Luana Leite e Thaís Carli<br>
								 Execução Musical: Fernando Bresolin e Vinícius De Lisieux</h3>
