						         <h3 style="background-color: #952028; text-align: center; color: white;">Espetáculo: A Menina Boba</h3>
						         <h3 style="color: black;">Aula baseada na obra poética “A Menina Boba”, de Oneyda Alvarenga (1911-1984) e no ciclo de canções de Claudio Santoro, que musicou quatro poemas da poetisa, no ano de 1940. A profunda amizade entre Oneyda e Mário de Andrade e o esforço de Oneyda para afirmar-se como poeta e artista nas décadas de 30 e 40 são recontados através de um olhar poético. Seu jeito simples, sua poesia e a sinceridade de suas confissões nas cartas que troca com Mário de Andrade foram fonte de inspiração para a criação desta obra, que se baseia na musicalidade da voz e no movimento corporal para re-construir memórias, entrelaçando fatos reais e ficcionais, brincando com o canto e a voz falada em um jogo poético da voz em cena. </h3>
