					        <h3>Na peça, uma jovem atriz inexperiente e emocionalmente afetada por uma tragédia se muda de cidade em busca de um recomeço. Em meio às dificuldades do mundo da arte, conhece a famosa e misteriosa Luiza Fontenelle, atriz veterana, frustrada com a bajulação e a superficialidade do meio artístico em que vive. Transitando do tom cômico ao dramático, a peça é apresentada de maneira metateatral, como num ambiente de ensaio. O público assiste aos bastidores e vê a mecânica da peça enquanto a narrativa mostra as angústias, os percalços e as vaidades que habitam a arte do Teatro</h3>
