					        <h3>Tem de haver algum tipo de permanência neste universo cambiante? Ilusões propõe uma reflexão aberta sobre os mitos do amor, da memória e da permanência ao contar a história de dois velhos casais. Será que o amor é mais do que uma complexa rede de histórias que contamos a nós mesmos e aos outros? Como saber o que é e o que não é uma ilusão? Discos voadores, linhas rosas no horizonte e pedras arredondadas são aqui testemunhas das respostas provisórias a estas perguntas.</h3>
