					        <h3>“Pegando do Resto” explora a linguagem única e ao mesmo tempo universal das máscaras larvárias, numa temática existencialista situada no universo do Teatro do Absurdo. O espetáculo é composto por quatro larvárias-personagens e duas larvárias puras. As personagens dão conta do enredo de Esperando Godot e as outras, de preparar o espaço cênico – dispor os objetos em cena, bem como apresentar e finalizar o espetáculo. Aqui as máscaras do Grupo Abaporu exploram o lusco-fusco dos dias, manipulando o espaço e o tempo. Enquanto esperam, o ócio desenvolve situações para mantê-las sempre um segundo atrás do ponteiro do relógio.</h3>
