				<h3>Espetáculo: Caminhos – Uma Intervenção Urbana</h3>
				<p2><strong>	
				Cia. Enviezada (Teresópolis/RJ)<br>
				Autoria e Direção: Zé Alex<br>
				Gênero: Intervenção Urbana - Performance<br>
