					        <h3 style="background-color: #952028; text-align: center; color: white;">Espetáculo: Caminhos – Uma Intervenção Urbana</h3>
					        <h3> Uma intervenção performática inserida no cotidiano do centro urbano. Meia hora antes do início do espetáculo o espectador recebe um aparelho de MP3 player ou pode baixar a trilha sonora do espetáculo em seu próprio celular, Ipod ou MP3, bastando acessar o site www.ciaenviezada.com. Todos apertarão Play ao mesmo tempo, para transitar por um percurso pré- determinado, onde as cenas vão acontecendo. Caminhos é um mergulho no mundo e nas questões do homem contemporâneo. Uma obra de arte aberta que busca ampliar a experiência humana para além do seu tempo.</h3>
					        <h4>Elenco: Alexandre Vollu, Anna Carolina Moraes, Claudia Martins, Marcelo Valentim, Natalia Soarez, Raphael Cassou, Regina Ramos e Viviane Oliveira </h4>
