					        <h3 style="background-color: #952028; text-align: center; color: white;">Chapeuzinho Vermelho</h3>
					        <h3 style="color: black;">A clássica personagem das fábulas infantis na contemporaneidade. Nesta montagem, a menina tem uma mãe sem tempo, um pai ausente, uma avó doente e solitária. A rua é perigosa e em casa o tédio briga com a vontade de brincar. O espetáculo mistura teatro, dança, música, contação de história e humor, abordando temas como a imaginação infantil, o medo e curiosidade da criança diante do desconhecido, numa reflexão sobre relações familiares. Enquanto um personagem conta a história, cenas de impacto visual e auditivo vão sendo produzidas por meio da composição de imagens, efeitos cenográficos e sonoros que transitam entre o cotidiano e o fantástico. Inédita no Brasil, a dramaturgia é de Joël Pommerat, um dos mais relevantes dramaturgos franceses da atualidade</h3>
					        <h4 style="color: black;">Elenco: Fabiane Severo, Guilherme Ferrêra, Henrique Gonçalves e Laura Hickmann</h4></h3>
