					        <h3>Do alto da cidade, sobre uma coluna, ergue-se a estátua do Príncipe Feliz. Adornada com folhas de ouro puro e pedras preciosas, a estátua é muito admirada pelos moradores da cidade. Do alto, o Príncipe Feliz consegue ver toda a feiura e miséria de sua cidade, e impossibilitado de ajudar, não tem escolha a não ser chorar. Ao iniciar amizade com uma andorinha o Príncipe Feliz tem a idéia de doar suas jóias às pessoas pobres da cidade. Uma linda história que fala de fraternidade, de amor ao próximo e, com muito cuidado, da morte.</h3>
