					        <h3 style="color: black;">A peça conta sobre a radialista Adelaide Fontana, que demitida após 25 anos de casa, quando comandava o “Suspiros ao Meio-Dia”, resolve invadir e se trancar no estúdio da Rádio Esperança para fazer um programa especial. Ambientado em 1974, tempo de ditadura militar brasileira e repressão aos meios de comunicação e às manifestações artísticas, entre sucessos musicais, ela revela aos ouvintes com humor e ironia os reais motivos de sua saída. O espetáculo fala dos limites impostos às mulheres, principalmente as que ousavam desafiar o autoritarismo da época.</h3>
