						        <h3 style="background-color: #952028; text-align: center; color: white;">A Princesa e a Costureira</h3>
						        <h3>A Princesa e a Costureira tem como trama a história da jovem Cíntia, que está prometida em casamento para o príncipe do reino vizinho, porém se apaixona pela costureira responsável por confeccionar seu vestido de noiva. Vencedor do “PROAC /2015 - Apoio a projetos de promoção das manifestações culturais com temática LGBT”, o espetáculo é voltado para o público infanto-juvenil e traz a reflexão sobre a diversidade sexual, combatendo a intolerância e a violência contra as diferenças. Um teatro que diverte e ao mesmo tempo questiona, expondo a realidade sem abrir mão da fantasia e da ludicidade.</h3>
						        <h4>Elenco: Erika Coracini, Mariana Sancar e Marcio Ribeiro</h4>
