					        Fiu Fiu - Um encontro entre Pássaros é um espetáculo alegre que retrata uma história de encontros e desencontros entre dois passarinhos. Numa narrativa não linear, fazem uma abordagem sobre o amor, numa perspectiva de encontros e desencontros e a superação das frustrações, através de uma linguagem corporal própria e de movimentos precisos inspirados em uma dança popular da cultura cuiabana e personificados em dois pássaros, cômicos, lúdicos e únicos.</h3>
