					        <h3 style="color: black;">O Marujo e a Tempestade conta a história de um jovem marujo que chega em um porto e conhece uma moça. Os dois se apaixonam. Quando o marujo segue viagem, é pego de surpresa por uma tempestade. A moça, pressentindo o perigo, vai ao encontro dele, mas para que o amado seja salvo, um mistério deverá ser revelado. Como testemunhas, apenas a lua cheia e todo o público convidado. Performance de teatro de sombras contemporâneo realizada com um balão de nylon esférico inflável que serve de superfície de projeção para imagens de luz e sombra. Mistura as linguagens da intervenção cênica, da música, do teatro de animação, da instalação plástica com a interatividade dos artistas e do público.</h3>
					      	<h4>Sombristas Performers - Alexandre Fávero e Roger Lisboa</h4>
