					        <h3 style="color: black;">O espetáculo Bonecas de Pano tem seu texto dividido em três monólogos que se complementam, apresentando a transformação da mulher no decorrer da vida. Três atrizes compartilham as diferentes fases de uma mulher, em uma encenação que traz à tona questões como o aborto, a violência e o sexismo. A metáfora da “Boneca de Pano” perpassa a fala das atrizes que, em devaneios, trazem ao foco questões sobre a mulher na sociedade. Suas experiências enquanto mulheres e atrizes saltam da esfera privada para a pública num misto de denúncia e confissão.</h3>
