					        <h3>O espetáculo revela o universo mitológico do pesquisador/artista Franklin Joaquim Cascaes (1908-1983), no qual vivem bruxas, boitatás e outros seres fantásticos. Na obra de Cascaes está presente também a cultura folclórica da Ilha de Santa Catarina, os costumes de sua época e seus protestos que queriam chamar atenção para as mudanças que prejudicavam a natureza e favoreciam o individualismo, dito por ele bruxólico.</h3>
