					        <h3 style="color: black;">"Palestra de Hoje" é um espetáculo de que explora a interpretação com boneco e ator dividindo a cena no monólogo "Os Males do Tabaco", de Anton Tchekov. Na peça, Ivan Titerenovich é um dos mais distintos conhecedores de diversos assuntos. Sua experiência, de mais de trinta anos, lhe permite tratar com naturalidade os mais variados temas em suas conferências. O tema abordado em sua palestra de hoje deveria tratar dos males do tabaco. Contudo o peso do passado e a insatisfação com o presente revelam o desconforto psicológico e emocional de um homem que toma consciência de sua velhice e fracasso.</h3>
