					        <h3 style="background-color: #952028; text-align: center; color: white;">Intervenção Performática de Luzes e Sombras</h3>
					        <h3>Uma experiência sensível e sensitiva adentrando no espaço escuro, onírico e fantástico do mundo das luzes e sombras, onde as imagens sofrem transformações metamorfoseando-se entre os sentidos de cada um. A entreaberta Cia. Teatral e a Cia. Aérea de Teatro se unem neste evento performativo e recriam o universo evocado pelo artista Franklin Cascaes, ao identificar a Ilha de Santa Catarina como um celeiro de seres fantásticos, metamorfoseados, onde a natureza exuberante é protagonista e contem toda sorte da flora humana imagética do ilhéu.</h3>
