					        <h3 style="background-color: #952028; text-align: center; color: white;">Cabeça Oca</h3>
					        <h3 style="color: black;">Destinado ao público adulto, “Cabeça Oca" é uma metáfora para atitudes desprovidas de razão. Transita entre o real e o imaginário numa temática existencialista na qual algumas adversidades das relações humanas tais como a opressão, violência, intolerância, preconceito e alienação são abordadas de forma lúdica, onírica e parodoxal, pois, por meio de um boneco - oco, busca-se falar de algo que o ser humano foi perdendo em sua existência: a essência. Trata-se de um espetáculo de linguagem híbrida, rico em plasticidade que, além de bonecos, utiliza-se também de máscaras, vídeo e ação performativa na construção de uma dramaturgia poético-visual fortemente influenciada pelo surrealismo dentre outras vanguardas do século XX.</h3>
					        <button class="w3-button w3-right w3-white w3-border" onclick="document.getElementById('id88').style.display='none'">Fechar</button><br /><br><br>
