					        <h3>É chegado o momento em que Deus resolve contar ele mesmo a sua versão da criação. Em tom confessional, o despachado e quase sempre bem-humorado “Senhor do Universo” revela detalhes até então desconhecidos de sua obra, as suas ideias, as ações planejadas, os acasos e os acidentes de percurso, que irão levar a humanidade a tal grau de complexidade, deixando o próprio criador por vezes orgulhoso, por vezes perplexo, por vezes preocupado e outras extremamente decepcionado, mas nunca, em momento algum, arrependido.</h3>
