					        <h3 style="color: black;">Através da exploração do grotesco, o espetáculo busca as possibilidades cênico-musicais da execução de um repertório de Brecht na atualidade: da negação de uma estética do belo, do solista, da música como arte elevada, os corpos dos atores-músicos subvertem a sonoridade, traem um projeto higiênico; os performers em cena cantam, agem e dançam, buscando construir na presença do público noções compartilhadas do patético, do falso, do melodrama, do sonho e da redenção nas histórias cantadas de Weill e Brecht.</h3>
