					        <h3>A peça acompanha o cotidiano de uma típica família interiorana - pai, mãe, filha adolescente e avô - no ano de 1989. A trama do espetáculo é conduzida através de fragmentos de fatos marcantes veiculados através da programação de um televisor permanentemente ligado na casa da família. Um mergulho lúdico no tempo para refletir sobre os dias atuais como relacionamento interpessoal, alienação e pós-verdade.</h3>
